11	func TestScanReportsForbiddenActiveHits(t *testing.T) {
12		root := t.TempDir()
13		writeFile(t, root, "README.md", "Run ddx-agent with DDX_AGENT_DEBUG=1.\n")
14		writeFile(t, root, "agent.go", "package agent\n")
15		writeFile(t, root, "internal/provider/provider.go", "package provider\n")
16	
17		findings, err := Scan(Options{Root: root})
18		if err != nil {
19			t.Fatalf("Scan() error = %v", err)
20		}
21	
22		assertFinding(t, findings, "README.md", "ddx-agent")
23		assertFinding(t, findings, "README.md", "AGENT_*/DDX_AGENT_*")
24		assertFinding(t, findings, "agent.go", "root package agent")
25		if got := findSurface(findings, "internal/provider/provider.go", "root package agent"); got {
26			t.Fatalf("non-root package was reported as root package agent: %#v", findings)
27		}
28	}
