47	func TestRunReportOnlyReturnsFindingsAndNoError(t *testing.T) {
48		root := t.TempDir()
49		writeFile(t, root, "config.yaml", "path: .agent/session.jsonl\n")
50		var out bytes.Buffer
51	
52		findings, err := Run(Options{Root: root, Out: &out})
53		if err != nil {
54			t.Fatalf("Run() error = %v", err)
55		}
56		if len(findings) != 1 {
57			t.Fatalf("Run() findings = %d, want 1", len(findings))
58		}
59		if got := out.String(); !strings.Contains(got, "rename-noise: 1 unallowlisted old-name hit") || !strings.Contains(got, "config.yaml:1") {
60			t.Fatalf("Run() output = %q", got)
61		}
62	}
63	
64	func writeFile(t *testing.T, root, rel, content string) {
65		t.Helper()
66		path := filepath.Join(root, filepath.FromSlash(rel))
67		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
68			t.Fatalf("MkdirAll() error = %v", err)
69		}
70		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
71			t.Fatalf("WriteFile() error = %v", err)
72		}
73	}
74	
75	func assertFinding(t *testing.T, findings []Finding, path, surface string) {
76		t.Helper()
77		if !findSurface(findings, path, surface) {
78			t.Fatalf("missing finding for %s %s in %#v", path, surface, findings)
79		}
80	}
81	
82	func findSurface(findings []Finding, path, surface string) bool {
83		for _, f := range findings {
84			if f.Path == path && f.Surface == surface {
85				return true
86			}
87		}
88		return false
89	}
