11		"github.com/spf13/cobra"
12	)
13	
14	// MountOption customizes a mounted ddx-agent command tree.
15	type MountOption func(*mountConfig)
16	
17	type mountConfig struct {
18		use       string
19		short     string
20		long      string
21		stdin     io.Reader
22		stdout    io.Writer
23		stderr    io.Writer
24		version   string
25		buildTime string
26		gitCommit string
27	}
28	
29	// ExitError reports a non-zero CLI runner exit without terminating the parent
30	// process.
31	type ExitError struct {
32		Code int
33	}
34	
35	func (e *ExitError) Error() string {
36		return fmt.Sprintf("%s exited with code %d", productinfo.BinaryName, e.Code)
37	}
38	
39	// ExitCode extracts a process-style exit code from errors returned by mounted
40	// command execution.
41	func ExitCode(err error) (int, bool) {
42		var exitErr *ExitError
43		if errors.As(err, &exitErr) {
44			return exitErr.Code, true
45		}
46		return 0, false
47	}
48	
49	// WithUse overrides the Cobra command use/name string.
50	func WithUse(use string) MountOption {
51		return func(cfg *mountConfig) {
52			cfg.use = use
53		}
54	}
55	
56	// WithShort overrides the Cobra short help text.
57	func WithShort(short string) MountOption {
58		return func(cfg *mountConfig) {
59			cfg.short = short
60		}
61	}
62	
63	// WithLong overrides the Cobra long help text.
64	func WithLong(long string) MountOption {
65		return func(cfg *mountConfig) {
66			cfg.long = long
67		}
68	}
69	
70	// WithStdin injects stdin for mounted invocations.
71	func WithStdin(stdin io.Reader) MountOption {
72		return func(cfg *mountConfig) {
73			cfg.stdin = stdin
74		}
75	}
76	
77	// WithStdout injects stdout for mounted invocations.
78	func WithStdout(stdout io.Writer) MountOption {
79		return func(cfg *mountConfig) {
80			cfg.stdout = stdout
81		}
82	}
83	
84	// WithStderr injects stderr for mounted invocations.
85	func WithStderr(stderr io.Writer) MountOption {
86		return func(cfg *mountConfig) {
87			cfg.stderr = stderr
88		}
89	}
90	
91	// WithVersion injects version metadata for mounted invocations.
92	func WithVersion(version, buildTime, gitCommit string) MountOption {
93		return func(cfg *mountConfig) {
94			cfg.version = version
95			cfg.buildTime = buildTime
96			cfg.gitCommit = gitCommit
97		}
98	}
99	
100	// MountCLI returns a fresh, unattached Cobra root command. Most command paths
101	// are native Cobra commands; legacy compatibility remains for the default
102	// prompt path and explicitly delegated commands.
103	func MountCLI(opts ...MountOption) *cobra.Command {
104		cfg := mountConfig{
105			use:    productinfo.BinaryName,
106			short:  "Run the DDx agent CLI",
107			stdin:  os.Stdin,
108			stdout: os.Stdout,
109			stderr: os.Stderr,
110		}
111		for _, opt := range opts {
112			if opt != nil {
113				opt(&cfg)
114			}
115		}
116		cmd := &cobra.Command{
117			Use:           cfg.use,
118			Short:         cfg.short,
119			Long:          cfg.long,
120			SilenceUsage:  true,
121			SilenceErrors: true,
122			RunE: func(cmd *cobra.Command, args []string) error {
123				return runMounted(cfg, legacyArgs(cmd, args...))
124			},
125		}
126		addLegacyPersistentFlags(cmd)
127		addMountedSubcommands(cmd, cfg)
128		cmd.SetIn(cfg.stdin)
129		cmd.SetOut(cfg.stdout)
130		cmd.SetErr(cfg.stderr)
131		return cmd
132	}
133	
134	func addMountedSubcommands(root *cobra.Command, cfg mountConfig) {
135		root.AddCommand(nativeLogCommand())
136		root.AddCommand(nativeReplayCommand())
137		root.AddCommand(nativeUsageCommand())
138		root.AddCommand(nativeProvidersCommand())
139		root.AddCommand(nativeModelsCommand())
