574	// NeedsLegacyPassthrough reports whether argv should bypass Cobra traversal
575	// until the corresponding command path has native pflag definitions.
576	func NeedsLegacyPassthrough(args []string) bool {
577		valueFlags := map[string]bool{
578			"--backend":   true,
579			"--max-power": true,
580			"--max-iter":  true,
581			"--min-power": true,
582			"--model":     true,
583			"--model-ref": true,
584			"--p":         true,
585			"-p":          true,
586			"--preset":    true,
587			"--provider":  true,
588			"--reasoning": true,
589			"--system":    true,
590			"--work-dir":  true,
591		}
592		subcommands := map[string]bool{}
593		for _, name := range mountedSubcommands() {
594			subcommands[name] = true
595		}
596		for i := 0; i < len(args); i++ {
597			arg := args[i]
598			if strings.HasPrefix(arg, "-") {
599				if valueFlags[arg] && i+1 < len(args) {
600					i++
601				}
602				continue
603			}
604			if arg == "run" {
605				return false
606			}
607			switch arg {
608			case "log", "replay", "usage", "providers", "models", "check", "route-status", "corpus", "import", "update":
609				return false
610			case "catalog":
611				if i+1 < len(args) {
612					switch args[i+1] {
613					case "show", "models", "observations", "check", "update", "update-pricing":
614						return false
615					}
616				}
617				return true
618			default:
619				return subcommands[arg] || arg != ""
620			}
621		}
622		return false
623	}
