183	func bucketSuccessRate(b rootfizeau.OverrideClassBucket) float64 {
184		total := b.SuccessOutcomes + b.StalledOutcomes + b.FailedOutcomes + b.CancelledOutcomes + b.UnknownOutcomes
185		if total == 0 {
186			return 0
187		}
188		return float64(b.SuccessOutcomes) / float64(total)
189	}
